package app.velyntora.windows.layers;
import art.velyntora.core.DrawingView;
import javax.swing.*;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.concurrent.Callable;
import java.util.function.BiConsumer;
public final class LayersPanel extends JPanel {
 private record Layer(int index,String name,boolean visible,ImageIcon preview){}
 private final DefaultListModel<Layer> model=new DefaultListModel<>();private final JList<Layer> list=new JList<>(model);private boolean syncing;private final Runnable changed;private final BiConsumer<String,Callable<Boolean>> work;private long shownRevision=Long.MIN_VALUE;private int shownActive=-1;
 public LayersPanel(Runnable changed){this(changed,(message,action)->{try{action.call();changed.run();}catch(Exception e){throw new RuntimeException(e);}});}
 public LayersPanel(Runnable changed,BiConsumer<String,Callable<Boolean>> work){super(new BorderLayout());this.changed=changed;this.work=work;setPreferredSize(new Dimension(280,400));setBorder(BorderFactory.createEmptyBorder(8,8,8,8));JLabel heading=new JLabel("CAPAS");heading.setBorder(BorderFactory.createEmptyBorder(0,0,12,0));add(heading,BorderLayout.NORTH);list.setName("Capas");list.setCellRenderer((items,layer,index,selected,focused)->{JLabel row=new JLabel((layer.visible()?"● ":"○ ")+layer.name(),layer.preview(),JLabel.LEFT);row.setOpaque(true);row.setBorder(BorderFactory.createEmptyBorder(4,4,4,4));row.setBackground(selected?items.getSelectionBackground():items.getBackground());row.setForeground(selected?items.getSelectionForeground():items.getForeground());return row;});list.addMouseListener(new java.awt.event.MouseAdapter(){public void mouseClicked(java.awt.event.MouseEvent e){if(e.getClickCount()==2&&list.getSelectedIndex()>=0)properties();}});add(new JScrollPane(list),BorderLayout.CENTER);
  list.addListSelectionListener(e->{if(!syncing&&!e.getValueIsAdjusting()&&list.getSelectedValue()!=null){DrawingView.nativeSelectLayer(list.getSelectedValue().index());changed.run();}});
  JPanel buttons=new JPanel(new GridLayout(1,6,2,2));button(buttons,"+","Añadir capa",()->DrawingView.nativeAddLayer());button(buttons,"−","Eliminar capa",()->DrawingView.nativeDeleteLayer());button(buttons,"◉","Mostrar / ocultar capa",()->DrawingView.nativeToggleLayer());button(buttons,"↑","Subir capa",()->DrawingView.nativeMoveLayer(1));button(buttons,"↓","Bajar capa",()->DrawingView.nativeMoveLayer(-1));button(buttons,"▣","Duplicar capa",()->DrawingView.nativeLayerAction(0));
  JPanel bottom=new JPanel(new BorderLayout());bottom.add(buttons,BorderLayout.NORTH);JButton props=new JButton("Propiedades / mezcla");props.addActionListener(e->properties());bottom.add(props,BorderLayout.SOUTH);add(bottom,BorderLayout.SOUTH);
 }
 private void button(JPanel panel,String title,String tip,Callable<Boolean> action){JButton b=new JButton(title);app.velyntora.windows.app.EditorTheme.flat(b);b.setMargin(new Insets(4,2,4,2));b.setToolTipText(tip);b.getAccessibleContext().setAccessibleName(tip);b.addActionListener(e->work.accept(tip,action));panel.add(b);}
 public void refresh(){long revision=DrawingView.nativeRevision();int active=DrawingView.nativeActiveLayer();if(revision==shownRevision&&active==shownActive)return;syncing=true;try{model.clear();int count=DrawingView.nativeLayerCount();for(int i=count-1;i>=0;i--){int[] data=DrawingView.nativeLayerThumbnail(i);ImageIcon preview=null;if(data!=null&&data.length==48*48){BufferedImage image=new BufferedImage(48,48,2);image.setRGB(0,0,48,48,data,0,48);BufferedImage check=new BufferedImage(48,48,2);Graphics2D g=check.createGraphics();for(int y=0;y<48;y+=8)for(int x=0;x<48;x+=8){g.setColor(((x/8+y/8)&1)==0?Color.WHITE:Color.LIGHT_GRAY);g.fillRect(x,y,8,8);}g.drawImage(image,0,0,null);g.dispose();preview=new ImageIcon(check.getScaledInstance(40,40,Image.SCALE_SMOOTH));}model.addElement(new Layer(i,DrawingView.nativeLayerName(i)+(DrawingView.nativeTextStyle(i)!=null?" (texto)":DrawingView.nativeLayerIsImage(i)?" ◇":""),DrawingView.nativeLayerVisible(i),preview));}list.setSelectedIndex(count-1-active);shownRevision=revision;shownActive=active;}finally{syncing=false;}}
 private void properties(){int i=DrawingView.nativeActiveLayer();JTextField name=new JTextField(DrawingView.nativeLayerName(i));JCheckBox visible=new JCheckBox("Visible",DrawingView.nativeLayerVisible(i));JSlider opacity=new JSlider(0,100,Math.round(DrawingView.nativeIndexedLayerOpacity(i)*100));String[] modes={"Normal","Multiplicar","Subexponer el color","Sobreexponer el color","Superponer","Diferencia","Aclarar","Oscurecer","Trama","O exclusivo","Luz fuerte","Luz suave","Color","Luminosidad","Tono","Saturación"};JComboBox<String> blend=new JComboBox<>(modes);blend.setSelectedIndex(Math.min(modes.length-1,DrawingView.nativeLayerBlendMode(i)));JPanel form=new JPanel(new GridLayout(0,1));form.add(name);form.add(visible);form.add(new JLabel("Opacidad"));form.add(opacity);form.add(blend);if(JOptionPane.showConfirmDialog(this,form,"Propiedades",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION){String title=name.getText();boolean show=visible.isSelected();float alpha=opacity.getValue()/100f;int mode=blend.getSelectedIndex();work.accept("Propiedades de capa",()->DrawingView.nativeLayerProperties(i,title,show,alpha,mode));}}
}
